#!/bin/bash
# Generated By: Claude Code (claude-opus-5-5[1m])
#
# Self-check: --refresh re-renders ~/sandboxes/<name>/.vscode/tasks.json from
# the manifest. scode writes the file once, so after --recreate --profile, or
# on a sandbox from before --profile existed, the folder-open task runs an
# --ensure that fails. The fixture is the stale case: built as work, task says
# personal. The sandbox is stubbed Stopped — the rewrite must still happen,
# since the stale task is what runs before any deferred refresh could.
#
# Run: tests/test-tasks-json.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

fail() { echo "FAIL: $1" >&2; exit 1; }

mkdir -p "${TMP}/bin"
cat > "${TMP}/bin/openshell" << 'STUB'
#!/bin/bash
echo '{"sandboxes":[{"name":"sb-test","phase":"Stopped"}]}'
STUB
chmod +x "${TMP}/bin/openshell"
export PATH="${TMP}/bin:${PATH}"

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
    printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
        > "${WORK}/config/site.env"

FAKE_HOME="${TMP}/home"
PROBE="${FAKE_HOME}/sandboxes/probe-pr-1"
TASKS="${PROBE}/.vscode/tasks.json"
mkdir -p "${PROBE}/.vscode"
cat > "${PROBE}/manifest.json" << 'JSON'
{"name":"probe-pr-1","openshell_name":"sb-test","profile":"work",
 "repos":{"probe":{"url":"git@github.com:org/probe.git","ref":"pr/1"},
          "ref-less":{"url":"git@github.com:org/ref-less.git","ref":""}}}
JSON
STALE='{"tasks":[{"label":"sandbox","command":"sandbox.sh --ensure probe-pr-1 --profile personal"}]}'
sandbox_cmd() { jq -r '.tasks[] | select(.label == "sandbox") | .command' "$TASKS"; }

# --dryrun writes nothing.
echo "$STALE" > "$TASKS"
HOME="$FAKE_HOME" bash "${WORK}/scripts/sandbox.sh" --refresh probe-pr-1 --dryrun >/dev/null 2>&1 \
    || fail "--refresh --dryrun exited non-zero"
[[ "$(cat "$TASKS")" == "$STALE" ]] || fail "--refresh --dryrun rewrote tasks.json"

out="$(HOME="$FAKE_HOME" bash "${WORK}/scripts/sandbox.sh" --refresh probe-pr-1 2>&1)" \
    || fail "--refresh exited non-zero: ${out}"
want="${WORK}/scripts/sandbox.sh --ensure probe-pr-1 --profile work --repo git@github.com:org/probe.git --ref pr/1 --repo git@github.com:org/ref-less.git"
[[ "$(sandbox_cmd)" == "$want" ]] \
    || fail "tasks.json not re-rendered from the manifest
    want: ${want}
    got:  $(sandbox_cmd)"
[[ "$(jq -r '.tasks[] | select(.label == "bash") | .runOptions.runOn' "$TASKS")" == folderOpen ]] \
    || fail "bash task lost"

# A manifest from before .profile renders no --profile, rather than failing.
jq 'del(.profile)' "${PROBE}/manifest.json" > "${TMP}/m" && cat "${TMP}/m" > "${PROBE}/manifest.json"
HOME="$FAKE_HOME" bash "${WORK}/scripts/sandbox.sh" --refresh probe-pr-1 >/dev/null 2>&1 \
    || fail "--refresh with no manifest profile exited non-zero"
[[ "$(sandbox_cmd)" != *--profile* ]] || fail "profile-less manifest rendered a --profile"

echo "all tasks.json checks passed"
